import sys; sys.path.insert(0, __import__('pathlib').Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🎯 OBJECTIFS", 'fin', apropos("Tu branches une LED directement sur une pile 9 V, sans rien d'autre. Que va-t-il se passer, à ton avis ?", "La LED est **détruite** : elle laisse passer **beaucoup trop de courant** et grille en une fraction de seconde.\n\nPour la protéger, on place une **résistance** en série. Dans cette séance, tu vas apprendre à **choisir** cette résistance, à **lire** sa valeur grâce à ses bagues de couleur, et à **calculer** avec la loi d'Ohm.")),
    ("## 1️⃣", 'fin', clair("Une pile pousse des **charges électriques** dans les fils, un peu comme une pompe pousse de l'eau dans un tuyau.\n\n- La **tension (U)** dit **avec quelle force** on pousse : c'est la « pression ».\n- L'**intensité (I)** dit **combien** de charges passent chaque seconde : c'est le « débit ».\n- La **résistance (R)** dit **à quel point le passage est difficile** : c'est l'étroitesse du tuyau.\n\nUn tuyau plus étroit laisse passer **moins d'eau** : une résistance plus grande laisse passer **moins de courant**.") + "\n" + verifie(
        ("Dans l'analogie de l'eau, que représente l'intensité du courant ?", "Le **débit** de l'eau, c'est-à-dire la quantité qui passe en une seconde. Son unité est l'**ampère (A)**."),
        ("On rétrécit le tuyau sans changer la pompe. Que devient le débit ? Et en électricité ?", "Le débit **diminue**. En électricité, quand la **résistance augmente** avec la même pile, l'**intensité diminue**."),
        ("Associe chaque grandeur à son unité : tension, intensité, résistance.", "Tension → **volt (V)** ; intensité → **ampère (A)** ; résistance → **ohm (Ω)**.")) + "\n" + retenir("**U** se mesure en volts, **I** en ampères, **R** en ohms.", "Plus R est grande, moins il passe de courant.")),
    ("## 2️⃣", 'fin', clair("La loi d'Ohm relie les trois grandeurs : $U = R \\times I$.\n\nSi tu connais **deux** grandeurs, tu peux toujours trouver la **troisième**. Pour ne pas te tromper, suis toujours les mêmes étapes :\n\n1. **Écris** ce que tu cherches (U, R ou I).\n2. **Choisis** la formule avec le cercle : tu caches la grandeur cherchée.\n3. **Convertis** les unités en V, A et Ω (des mA deviennent des A).\n4. **Calcule**.\n5. **Vérifie** que le résultat est logique (ordre de grandeur).") + "\n" + erreurs("Oublier de convertir les mA en A : 20 mA = **0,02 A** (et pas 20).", "Mélanger les formules : le cercle sert à retrouver la bonne.") + "\n" + verifie(
        ("Une résistance de 100 Ω est traversée par 0,05 A. Quelle est la tension à ses bornes ?", "On cherche U : $U = R \\times I = 100 \\times 0{,}05 = 5\\,\\mathrm{V}$."),
        ("Une tension de 5 V est appliquée à un composant qui laisse passer 20 mA. Quelle est sa résistance ?", "On cherche R : $R = \\dfrac{U}{I} = \\dfrac{5}{0{,}02} = 250\\,\\Omega$ (20 mA = 0,02 A)."),
        ("Une résistance de 450 Ω est alimentée en 9 V. Quelle intensité la traverse ?", "On cherche I : $I = \\dfrac{U}{R} = \\dfrac{9}{450} = 0{,}02\\,\\mathrm{A} = 20\\,\\mathrm{mA}$.")) + "\n" + retenir("$U = R \\times I$ ; $I = \\dfrac{U}{R}$ ; $R = \\dfrac{U}{I}$.", "Toujours convertir en V, A et Ω avant de calculer.")),
    ("## 3️⃣", 'fin', clair("Les valeurs en électronique sont souvent **très grandes** ou **très petites**. On utilise des **préfixes** pour éviter d'écrire trop de zéros :\n\n- **k** (kilo) = mille : 1 kΩ = 1 000 Ω\n- **M** (méga) = un million : 1 MΩ = 1 000 000 Ω\n- **m** (milli) = un millième : 1 mA = 0,001 A\n\nPour passer de l'unité aux milli, on **multiplie par 1 000** ; dans l'autre sens, on **divise par 1 000**.") + "\n" + verifie(
        ("Convertis 3 300 Ω en kΩ.", "$3\\,300\\,\\Omega = 3{,}3\\,\\mathrm{k\\Omega}$ (on divise par 1 000)."),
        ("Convertis 0,015 A en mA.", "$0{,}015\\,\\mathrm{A} = 15\\,\\mathrm{mA}$ (on multiplie par 1 000)."),
        ("Convertis 47 mA en A.", "$47\\,\\mathrm{mA} = 0{,}047\\,\\mathrm{A}$ (on divise par 1 000).")) + "\n" + retenir("kilo = ×1 000 ; méga = ×1 000 000 ; milli = ÷ 1 000.", "A → mA : on multiplie par 1 000. mA → A : on divise par 1 000.")),
    ("## 4️⃣", 'fin', clair("Une résistance est trop petite pour qu'on y écrive sa valeur : on la **code avec des bagues de couleur**. Chaque couleur correspond à un **chiffre** :\n\n**N**oir 0 · **M**arron 1 · **R**ouge 2 · **O**range 3 · **J**aune 4 · **V**ert 5 · **B**leu 6 · **V**iolet 7 · **G**ris 8 · **B**lanc 9\n\nPetite phrase pour s'en souvenir : « **N**e **M**angez **R**ien **O**u **J**eûnez **V**oilà **B**ien **V**otre **G**rande **B**êtise ».\n\nOn lit **de gauche à droite**, en partant de la bague la plus proche d'un bord (la bague de tolérance dorée ou argentée est à droite) :\n\n1. les **deux premières bagues** donnent **deux chiffres** ;\n2. la **troisième** donne le **nombre de zéros** à ajouter (le multiplicateur) ;\n3. la **quatrième** donne la **tolérance** (précision).") + "\n" + verifie(
        ("Décode : Rouge – Rouge – Marron.", "Rouge = 2, rouge = 2, marron = 1 zéro : **220 Ω**."),
        ("Décode : Orange – Orange – Rouge.", "Orange = 3, orange = 3, rouge = 2 zéros : $3\\,300\\,\\Omega = 3{,}3\\,\\mathrm{k\\Omega}$."),
        ("Décode : Jaune – Violet – Orange.", "Jaune = 4, violet = 7, orange = 3 zéros : $47\\,000\\,\\Omega = 47\\,\\mathrm{k\\Omega}$.")) + "\n" + retenir("Les deux premières bagues : deux chiffres. La troisième : le nombre de zéros. La quatrième : la tolérance.", "On lit toujours en partant du côté opposé à la bague dorée ou argentée.")),
    ("## 5️⃣", 'fin', clair("Une **LED** laisse passer le courant **dans un seul sens** et n'accepte qu'un **courant faible** (environ 20 mA). Si on la branche sans protection, elle reçoit trop de courant et grille.\n\nOn place donc une **résistance de limitation** **en série**. On la calcule avec la loi d'Ohm : la résistance doit « absorber » la tension en trop.\n\n$R = \\dfrac{U_{pile} - U_{LED}}{I_{LED}}$\n\nPour une pile de 9 V, une LED rouge ($U_{LED} \\approx 2\\,\\mathrm{V}$) et $I = 20\\,\\mathrm{mA}$ : $R = \\dfrac{9 - 2}{0{,}02} = 350\\,\\Omega$. On choisit la valeur normalisée **juste au-dessus** (390 Ω) : la LED reçoit un peu moins de courant, donc elle est protégée.") + "\n" + verifie(
        ("Pourquoi faut-il une résistance en série avec une LED ?", "Pour **limiter le courant** : sans elle, la LED reçoit un courant trop fort et est détruite."),
        ("Calcule la résistance pour une LED rouge (2 V, 20 mA) alimentée en 5 V.", "$R = \\dfrac{5 - 2}{0{,}02} = 150\\,\\Omega$ (valeur normalisée : 150 Ω)."),
        ("Pourquoi choisit-on la valeur normalisée juste **au-dessus** du résultat ?", "Une résistance plus grande donne un courant **plus faible** : la LED reste sous son courant maximal et n'est pas détruite.")) + "\n" + erreurs("Brancher la LED à l'envers : elle ne s'allume pas (patte longue = **anode +**).", "Oublier de retirer la tension de la LED ($U_{LED}$) dans le calcul.")),
]
